import sys

MOD = 998244353

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)

    # by[x][left] contains right endpoints of constraints targeting x.
    by = [[[] for _ in range(n + 1)] for _ in range(n + 1)]
    for _ in range(m):
        l, r, x = next(it), next(it), next(it)
        by[x][l].append(r)

    # lim[x][l] is the minimum right endpoint among constraints for x
    # whose left endpoint is at least l.
    lim = [[n + 1] * (n + 1) for _ in range(n + 1)]
    for x in range(1, n + 1):
        cur = n + 1
        for l in range(n, 0, -1):
            if by[x][l]:
                cur = min(cur, min(by[x][l]))
            lim[x][l] = cur

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for root in range(l, r + 1):
                # The root is maximum on [l,r]; this is forbidden exactly
                # when some constraint for root is contained in [l,r].
                if r < lim[root][l]:
                    total = (total + dp[l][root - 1] * dp[root + 1][r] % MOD
                             * comb[length - 1][root - l]) % MOD
            dp[l][r] = total

    print(dp[1][n])

if __name__ == "__main__":
    main()

