import sys
from array import array
MOD=998244353

def main():
    d = list(map(int, sys.stdin.buffer.read().split()))
    n, m = d[:2]
    a = [x - 1 for x in d[2:]]
    rev = [[] for _ in range(n)]
    deg = [0] * n
    for i, p in enumerate(a):
        rev[p].append(i)
        deg[p] += 1
    q = [i for i in range(n) if deg[i] == 0]
    order = []
    for v in q:
        order.append(v)
        p = a[v]
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    dp = [None] * n
    for v in order:
        cur = array('I', [0]) * (m + 1)
        for x in range(1, m + 1):
            cur[x] = 1
        for ch in rev[v]:
            c = dp[ch]
            if c is not None:
                s = 0
                for x in range(1, m + 1):
                    s += c[x]
                    if s >= MOD:
                        s -= MOD
                    cur[x] = cur[x] * s % MOD
                dp[ch] = None
        dp[v] = cur

    seen = [0] * n
    ans = 1
    for st in range(n):
        if deg[st] and not seen[st]:
            cyc = []
            v = st
            while not seen[v]:
                seen[v] = 1
                cyc.append(v)
                v = a[v]
            w = array('I', [0]) * (m + 1)
            for x in range(1, m + 1):
                w[x] = 1
            for r in cyc:
                for ch in rev[r]:
                    c = dp[ch]
                    if c is not None:
                        s = 0
                        for x in range(1, m + 1):
                            s += c[x]
                            if s >= MOD:
                                s -= MOD
                            w[x] = w[x] * s % MOD
                        dp[ch] = None
            total = 0
            for x in range(1, m + 1):
                total = (total + w[x]) % MOD
            ans = ans * total % MOD
    print(ans)

if __name__ == '__main__':
    main()

