import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]

    primes = set()
    for x in a:
        y = x
        q = 2
        while q * q <= y:
            if y % q == 0:
                primes.add(q)
                while y % q == 0:
                    y //= q
            q += 1
        if y > 1:
            primes.add(y)

    answer = 1
    for p in primes:
        exponents = []
        total = 0
        for x in a:
            y = x
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            exponents.append(e)
            total += e

        # cur is the current valuation relative to the first one;
        # mn is its minimum over the prefix.
        powers = {0: 1}
        z = 1
        for k in range(1, total + 1):
            z = z * p % MOD
            powers[k] = z
        z = 1
        ip = pow(p, MOD - 2, MOD)
        for k in range(1, total + 1):
            z = z * ip % MOD
            powers[-k] = z

        dp = {(0, 0): 1}
        for e in exponents:
            nd = {}
            steps = (e, -e) if e else (0,)
            for (cur, mn), val in dp.items():
                for step in steps:
                    nc = cur + step
                    key = (nc, mn if mn < nc else nc)
                    nd[key] = (nd.get(key, 0) + val * powers[nc]) % MOD
            dp = nd

        minimum_factor = {}
        contribution = 0
        for (cur, mn), val in dp.items():
            if mn not in minimum_factor:
                minimum_factor[mn] = pow(p, -n * mn, MOD)
            contribution = (contribution + val * minimum_factor[mn]) % MOD
        answer = answer * contribution % MOD

    print(answer)

if __name__ == '__main__':
    main()

