        a, p, b, q = data[2 + 4*i: 6 + 4*i]
        machines.append((a, p, b, q))
        upper = min(upper, max(budget * a // p, budget * b // q) + 1)

    def feasible(capacity):
        spent = 0
        for a, p, b, q in machines:
            best = 10**30
            if p * b <= q * a:
                for t in range(a):
                    remaining = capacity - t * b
                    s = 0 if remaining <= 0 else (remaining + a - 1) // a
                    cost = t * q + s * p
                    if cost < best:
                        best = cost
            else:
                for s in range(b):
