                    cost = s * p + t * q
                    if cost < best:
                        best = cost
            spent += best
            if spent > budget:
                return False
        return True

    low = 0
    while upper - low > 1:
        mid = (low + upper) // 2
        if feasible(mid):
            low = mid
        else:
            upper = mid
