class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        m = min(n, x)
        dp = [0] * (m + 1)
        dp[0] = 1

        for _ in range(n):
            nxt = [0] * (m + 1)
            for used, ways in enumerate(dp):
                if ways == 0:
                    continue
                # Put the performer on an already occupied stage.
                nxt[used] = (nxt[used] + ways * used) % MOD
                # Put them on a new stage: choose its label and its score.
                if used < m:
                    nxt[used + 1] = (
                        nxt[used + 1] + ways * (x - used) * y
                    ) % MOD
            dp = nxt

        return sum(dp) % MOD

