class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        depth = [0] * (m + 1)
        for x in range(2, m + 1):
            depth[x] = 1 + depth[x.bit_count()]
        good = [False] * (m + 1)
        for j in range(1, m + 1):
            good[j] = depth[j] <= k - 1
        fact = [1] * (m + 1)
        for i in range(1, m + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (m + 1)
        invfact[m] = pow(fact[m], MOD - 2, MOD)
        for i in range(m, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD
        ans = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = m - i - 1
                for t in range(rem + 1):
                    pop = prefix_ones + t
                    if pop and good[pop]:
                        ways = fact[rem] * invfact[t] % MOD * invfact[rem - t] % MOD
                        ans = (ans + ways) % MOD
                prefix_ones += 1
        return ans

