import sys
import heapq


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    rows = [x.decode() for x in data[1:]]
    INF = 10**9
    dist = [[INF] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for i in range(n):
        row = rows[i]
        for j, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(heap, (1, i, j))

    # If every pair has a direct edge (apart from equal vertices),
    # these are already the minimum possible lengths.
    if all(dist[i][j] < INF for i in range(n) for j in range(n)):
        sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))
        return

    while heap:
        value, a, b = heapq.heappop(heap)
        if dist[a][b] != value:
            continue
        new_value = value + 2
        for c in range(26):
            left = incoming[a][c]
            right = outgoing[b][c]
            if not left or not right:
                continue
            for x in left:
                dx = dist[x]
                for y in right:
                    if dx[y] > new_value:
                        dx[y] = new_value
                        heapq.heappush(heap, (new_value, x, y))

    out = []
    for row in dist:
        out.append(' '.join(str(-1 if v == INF else v) for v in row))
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    main()

