import sys

def mountain(n):
    if n<=0: return 0
    return ((n//(n & -n)) & 3)==1

def main():
    z=list(map(int,sys.stdin.buffer.read().split()))
    if not z:return
    n=z[0]; a=z[1:]
    # The relevant representatives are around binary block boundaries.  Include
    # boundaries aligned with each supplied displacement and their local shifts.
    cand={0}
    for k in range(1,101):
        p=1<<k
        for x in a:
            for d in (-3,-2,-1,0,1,2,3):
                q=p-x+d
                if q>=0: cand.add(q)
        for i in range(1,n):
            q=p-(a[i]-a[i-1])
            if q>=0: cand.add(q)
    best=0
    for x in cand:
        s=0
        for v in a:
            s+=mountain(x+v+1)
        if s>best:best=s
    print(best)
