class Solution:
    def permute(self, n: int, k: int):
        fac = [1] * (n + 1)
        for i in range(1, n + 1):
            fac[i] = fac[i - 1] * i

        odd = (n + 1) // 2
        even = n // 2
        used = [False] * (n + 1)

        def completions(o, e, previous):
            remaining = o + e
            if remaining == 0:
                return 1
            nxt = 1 - previous
            required_odd = (remaining + 1) // 2 if nxt == 1 else remaining // 2
            required_even = remaining - required_odd
            if o != required_odd or e != required_even:
                return 0
            return fac[o] * fac[e]

        total = 0
        for x in range(1, n + 1):
            is_odd = x & 1
            total += completions(odd - is_odd, even - (not is_odd), is_odd)
        if k > total:
            return []

        answer = []
        previous = None
        for _ in range(n):
            for x in range(1, n + 1):
                if used[x]:
                    continue
                is_odd = x & 1
                if previous is not None and is_odd == previous:
                    continue
                new_odd = odd - is_odd
                new_even = even - (not is_odd)
                block = completions(new_odd, new_even, is_odd)
                if k > block:
                    k -= block
                else:
                    used[x] = True
                    answer.append(x)
                    odd, even, previous = new_odd, new_even, is_odd
                    break
        return answer

