class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        p = [1] * n
        for i in range(1, n):
            p[i] = (p[i - 1] * 10) % k

        coeff = [0] * m
        for j in range(m):
            mirror = n - 1 - j
            coeff[j] = p[mirror]
            if mirror != j:
                coeff[j] = (coeff[j] + p[j]) % k

        # dp[pos, r] says whether positions pos..m-1 can contribute
        # residue r modulo k.
        dp = bytearray((m + 1) * k)
        dp[m * k] = 1
        for pos in range(m - 1, -1, -1):
            base = (pos + 1) * k
            out = pos * k
            for residue in range(k):
                for digit in range(10):
                    if dp[base + (residue - coeff[pos] * digit) % k]:
                        dp[out + residue] = 1
                        break

        # Greedily choose the largest possible digit in the left half.
        ans = []
        current = 0
        for pos in range(m):
            first = (pos == 0)
            for digit in range(9, 0 if first else -1, -1):
                new_residue = (current + coeff[pos] * digit) % k
                if dp[(pos + 1) * k + (-new_residue) % k]:
                    ans.append(str(digit))
                    current = new_residue
                    break

        left = ''.join(ans)
        return left + (left[-2::-1] if n % 2 else left[::-1])

