class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        n = len(s)
        answer = n  # Delete every character.

        # The final positive frequency can be any value from 1 through n.
        # For a fixed k, every letter has desired count either 0 or k.
        for k in range(1, n + 1):
            dp = [cnt[0], abs(cnt[0] - k)]
            for i in range(1, 26):
                nxt = [10**18, 10**18]
                for previous in (0, 1):
                    old_target = k if previous else 0
                    for current in (0, 1):
                        target = k if current else 0
                        # A surplus at i-1 can be changed directly into
                        # a deficit at i, saving one operation per unit.
                        saving = min(
                            max(cnt[i - 1] - old_target, 0),
                            max(target - cnt[i], 0),
                        )
                        value = (dp[previous] + abs(cnt[i] - target)
                                 - saving)
                        if value < nxt[current]:
                            nxt[current] = value
                dp = nxt
            answer = min(answer, dp[0], dp[1])

        return answer

