class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)
        inf = n + 1

        def occurrences(t):
            if not t:
                return []
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        def next_occurrence(t):
            nxt = [inf] * (n + 1)
            for pos in occurrences(t):
                nxt[pos] = pos
            for i in range(n - 1, -1, -1):
                if nxt[i + 1] < nxt[i]:
                    nxt[i] = nxt[i + 1]
            return nxt

        nb = next_occurrence(b) if b else None
        nc = next_occurrence(c) if c else None
        starts = occurrences(a) if a else range(n + 1)
        answer = inf

        for start in starts:
            pos = start + len(a)
            if b:
                pos = nb[pos] if pos <= n else inf
                if pos == inf:
                    continue
                pos += len(b)
            if c:
                pos = nc[pos] if pos <= n else inf
                if pos == inf:
                    continue
                end = pos + len(c)
            else:
                end = pos
            answer = min(answer, end - start)

        return -1 if answer == inf else answer

