import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    dist = [None] * n
    answer = [0] * n
    for start in range(n):
        if dist[start] is not None:
            continue
        dist[start] = 0
        stack = [start]
        component = []
        while stack:
            v = stack.pop()
            component.append(v)
            for w, z in adj[v]:
                expected = dist[v] ^ z
                if dist[w] is None:
                    dist[w] = expected
                    stack.append(w)
                elif dist[w] != expected:
                    print(-1)
                    return

        ones = [0] * 30
        for v in component:
            value = dist[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1
        size = len(component)
        shift = 0
        for bit in range(30):
            if 2 * ones[bit] > size:
                shift |= 1 << bit
        for v in component:
            answer[v] = dist[v] ^ shift

    print(*answer)

solve()

