from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        post = []
        pos = [0] * n
        stack = [(0, 0)]
        while stack:
            x, next_child = stack[-1]
            if next_child < len(children[x]):
                y = children[x][next_child]
                stack[-1] = (x, next_child + 1)
                stack.append((y, 0))
            else:
                pos[x] = len(post)
                post.append(x)
                stack.pop()

        size = [0] * n
        for x in post:
            size[x] = 1 + sum(size[y] for y in children[x])

        text = ''.join(s[x] for x in post)

        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i-k] == text[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i-k-1] == text[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for x in range(n):
            end = pos[x]
            length = size[x]
            start = end - length + 1
            if length & 1:
                answer[x] = odd[(start + end) // 2] >= length // 2 + 1
            else:
                answer[x] = even[(start + end) // 2 + 1] >= length // 2
        return answer

