class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        tree = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(line, node, left, right):
            current = tree[node]
            if current is None:
                tree[node] = line
                return
            mid = (left + right) // 2
            if value(line, mid) > value(current, mid):
                tree[node], line = line, current
            if left == right:
                return
            if value(line, left) > value(tree[node], left):
                add(line, node * 2, left, mid)
            elif value(line, right) > value(tree[node], right):
                add(line, node * 2 + 1, mid + 1, right)

        def query(x, node, left, right):
            line = tree[node]
            answer = value(line, x) if line is not None else -10**30
            if left == right:
                return answer
            mid = (left + right) // 2
            if x <= mid:
                return max(answer, query(x, node * 2, left, mid))
            return max(answer, query(x, node * 2 + 1, mid + 1, right))

        add((nums[0], 0), 1, 0, n - 1)
        score = 0
        for j in range(1, n):
            score = query(j, 1, 0, n - 1)
            add((nums[j], score - j * nums[j]), 1, 0, n - 1)
        return score

