import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        if n == m:
            return -1 if self._is_prime(n) else n

        digits = len(str(n))
        limit = 10 ** digits

        prime = bytearray(b'\x01') * limit
        prime[0] = prime[1] = 0
        p = 2
        while p * p < limit:
            if prime[p]:
                prime[p * p:limit:p] = b'\x00' * (((limit - 1 - p * p) // p) + 1)
            p += 1

        if prime[n] or prime[m]:
            return -1

        inf = 10 ** 30
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]
        powers = [10 ** i for i in range(digits)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10
                if digit:
                    nxt = value - power
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))
                if digit != 9:
                    nxt = value + power
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

        return -1

    @staticmethod
    def _is_prime(x):
        if x < 2:
            return False
        p = 2
        while p * p <= x:
            if x % p == 0:
                return False
            p += 1
        return True

