from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        ans = 0
        # First condition: for a split at i,j, j-i must be at least i.
        for i in range(1, n - 1):
            if z[i] >= i:
                ans += max(0, n - 2 * i)

        # For each distance d=j-i, find equal runs at positions i and i+d.
        for d in range(1, n):
            run = 0
            for i in range(n - d - 1, -1, -1):
                if nums[i] == nums[i + d]:
                    run += 1
                else:
                    run = 0
                if i >= 1 and i + 2 * d <= n and run >= d:
                    # Avoid pairs already counted by the first condition.
                    if not (z[i] >= i and d >= i):
                        ans += 1
        return ans

