class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        if threshold <= 0:
            return -1
        incoming = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            incoming[b].append((a, w))
            weights.append(w)
        weights = sorted(set(weights))

        def possible(limit):
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in incoming[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        if count == n:
                            return True
                        stack.append(u)
            return count == n

        if not possible(weights[-1]):
            return -1
        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if possible(weights[mid]):
                hi = mid
            else:
                lo = mid + 1
        return weights[lo]

